const CACHE='voyz-shell-v3-2';
const ASSETS=['./','index.html','styles.css','v2.css','v3.css','cloud-ui.css','app.js','storage.js','exports.js','photos.js','brand.js','cloud-config.js','cloud-sync.js','cloud-ui.js','offline.js','vendor/pdf-lib.min.js','vendor/supabase.js','assets/voyz-logo.png','assets/voyz-icon.jpg','assets/voyz-app-icon.svg','manifest.webmanifest','credits.html'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('voyz-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin||!url.pathname.startsWith(new URL(self.registration.scope).pathname))return;if(e.request.mode==='navigate'||url.pathname.endsWith('/cloud-config.js')){e.respondWith(fetch(e.request).then(r=>{if(r.ok)caches.open(CACHE).then(c=>c.put(e.request,r.clone()));return r;}).catch(async()=>await caches.match(e.request)||await caches.match(new URL('./',self.registration.scope))));return;}e.respondWith(caches.match(e.request).then(hit=>hit||fetch(e.request).then(r=>{if(r.ok&&ASSETS.some(a=>new URL(a,self.registration.scope).pathname===url.pathname))caches.open(CACHE).then(c=>c.put(e.request,r.clone()));return r;})));});
